 void businessHome(){screen("��� � �� ����");text("��ȹ���� ���� �߽� ���� �帧: ���� �� ���� �� ���� �� ���ݡ����� �� ������");for(int i=0;i<businessDefinitions.length();i++){JSONObject m=businessDefinitions.optJSONObject(i);String key=m.optString("key");if(can(key+".read"))button(m.optString("label")+" �� "+rows(key).length()+"��",()->businessList(key));}button("���� Ȩ",()->dashboard());}
 JSONObject definition(String key){for(int i=0;i<businessDefinitions.length();i++){JSONObject m=businessDefinitions.optJSONObject(i);if(m.optString("key").equals(key))return m;}return null;}
 void businessList(String key){if(!can(key+".read")){error("������ ���� �����Դϴ�.");return;}if(definition(key)==null){rpc("businessCatalog",new JSONObject(),r->{businessDefinitions=r.getJSONArray("modules");businessList(key);});return;}group=key;JSONObject m=definition(key);screen(m.optString("label"));if(key.equals("taxRecords"))text("�ܺ� �߱ޡ����� ������ ����մϴ�. �� �ۿ��� ����û ���� �߱ޡ������� �������� �ʽ��ϴ�.");if(key.equals("labor"))text("�ϼ� �� �ܰ��� ��ȹ ����Դϴ�. ���� ������ ���� ���� ���� �Ǵ� ����� ��ο� ������ ����մϴ�.");button("? ��� �",()->businessHome());if(can(key+".write"))button(key.equals("documents")?"�� ���忡�� ���� ����":"�� �� �׸�",()->{if(key.equals("documents"))newDocument(null);else businessEdit(key,null);});JSONArray list=rows(key);for(int i=0;i<list.length();i++){JSONObject r=list.optJSONObject(i);if(r==null)continue;String sub=key.equals("documents")?r.optString("number")+" �� "+r.optString("status"):key.equals("paymentPlans")?"���� "+money(r.optDouble("amount"))+" / ������ "+money(r.optDouble("amount")-r.optDouble("paid")):key.equals("labor")?"��ȹ "+money(r.optDouble("days")*r.optDouble("rate")):r.optString("status",r.optString("date"));button(r.optString("name")+"\n"+sub,()->businessDetails(key,r));}if(list.length()==0)text("���� ��ϵ� �׸��� �����ϴ�.");button("���ΰ�ħ",()->reload());}
 void businessDetails(String key,JSONObject row){if(key.equals("documents")){rpc("documentView",obj("id",row.optString("id")),r->{screen(row.optString("number"));JSONArray lines=r.getJSONArray("lines");for(int i=0;i<lines.length();i++)text(lines.optString(i));if(can("export"))button("PDF ����",()->rpc("documentView",obj("id",row.optString("id"),"export",true),d->savePdf(d.getJSONArray("lines"),row.optString("number")+".pdf")));if(can("documents.write")){button("�����",()->newDocument(row));button("���� ��� �� �̷� ����",()->{EditText reason=new EditText(this);new AlertDialog.Builder(this).setTitle("��� ����").setView(reason).setNegativeButton("�ݱ�",null).setPositiveButton("��� ���",(d,w)->rpc("cancelDocument",obj("id",row.optString("id"),"reason",reason.getText().toString(),"version",version==null?JSONObject.NULL:version),x->reload())).show();});}button("���",()->businessList(key));});return;}JSONObject m=definition(key);screen(row.optString("name"));JSONArray fields=m.optJSONArray("fields");for(int i=0;i<fields.length();i++){JSONObject f=fields.optJSONObject(i);String value=row.optString(f.optString("key"));if(f.optString("type").equals("projects"))value=lookup("projects",value);detailRow(f.optString("label"),value);}if(key.equals("paymentPlans")){detailRow("����� / ������",money(row.optDouble("paid"))+" / "+money(row.optDouble("amount")-row.optDouble("paid")));if(can("paymentPlans.write")&&can("projects.write")&&can("transactions.write")){button("���� ���� / ���� �ݿ�",()->settleBusiness(row));JSONArray all=rows("transactions");for(int i=0;i<all.length();i++){JSONObject t=all.optJSONObject(i);if(t==null||!t.optString("plan").equals(row.optString("id"))||t.optString("status").equals("���"))continue;button("�Է� ���� �� "+t.optString("date")+" �� "+money(t.optDouble("amount")),()->{EditText reason=new EditText(this);new AlertDialog.Builder(this).setTitle("��� �Է� ���� (��ȯ �ƴ�)").setView(reason).setNegativeButton("�ݱ�",null).setPositiveButton("����",(d,w)->rpc("reverseSettlement",obj("id",t.optString("id"),"reason",reason.getText().toString(),"version",version==null?JSONObject.NULL:version),v->reload())).show();});}}}if(can(key+".write")){button("����",()->businessEdit(key,row));if(!key.equals("taxRecords"))button("����",()->new AlertDialog.Builder(this).setMessage("�����ұ��?").setNegativeButton("���",null).setPositiveButton("����",(d,w)->{JSONObject next=cloneState();JSONArray keep=new JSONArray(),a=rows(key);for(int i=0;i<a.length();i++)if(!a.optJSONObject(i).optString("id").equals(row.optString("id")))keep.put(a.optJSONObject(i));objMerge(next,key,keep);save(next,()->businessList(key));}).show());}button("���",()->businessList(key));}
 void businessEdit(String key,JSONObject original){if(!can(key+".write")){error("���� ������ �����ϴ�.");return;}if(key.equals("company")&&original==null&&rows(key).length()>0){error("��ϵ� ����� ������ �����ϼ���.");return;}JSONObject record=original==null?obj("id",UUID.randomUUID().toString()):cloneObj(original),m=definition(key);screen(m.optString("label")+" �� �Է�");JSONArray fields=m.optJSONArray("fields");LinkedHashMap<String,View> inputs=new LinkedHashMap<>();for(int i=0;i<fields.length();i++){JSONObject f=fields.optJSONObject(i);String name=f.optString("key"),kind=f.optString("type"),value=record.optString(name);View v;if(kind.equals("projects"))v=reference(f.optString("label"),"projects",value);else if(kind.equals("select"))v=select(f.optString("label"),f.optString("options").split(","),value);else v=input(f.optString("label"),value.isEmpty()&&kind.equals("number")?"0":value,kind.equals("number")?InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL:InputType.TYPE_CLASS_TEXT);inputs.put(name,v);}button("����",()->{try{for(int i=0;i<fields.length();i++){JSONObject f=fields.getJSONObject(i);String name=f.getString("key"),kind=f.getString("type");View v=inputs.get(name);if(kind.equals("projects"))record.put(name,((String[])v.getTag())[((Spinner)v).getSelectedItemPosition()]);else if(kind.equals("select"))record.put(name,((Spinner)v).getSelectedItem().toString());else if(kind.equals("number"))record.put(name,Double.parseDouble(((EditText)v).getText().toString()));else record.put(name,((EditText)v).getText().toString().trim());}JSONObject next=cloneState();putRow(next,key,record);save(next,()->businessList(key));}catch(Exception e){error("�Է°��� Ȯ���ϼ���. "+e.getMessage());}});button("���",()->businessList(key));}
 void newDocument(JSONObject previous){screen("���忡�� ���� ����");text("�߱� ��� ������ �����մϴ�. ���ڼ��ݰ�꼭 �߱� ����� �ƴմϴ�.");Spinner project=reference("����","projects",previous==null?"":previous.optString("project"));Spinner kind=select("���� ����",new String[]{"�ŷ�������","�����༭","�۾�Ȯ�μ�","����ϷẸ����","�Ա�Ȯ�μ�","���ں���Ȯ�μ�"},previous==null?"�ŷ�������":previous.optString("kind"));EditText memo=input("���� �� ���� Ȯ�� �޸�","",InputType.TYPE_CLASS_TEXT);final String requestId=UUID.randomUUID().toString();button("���� ����",()->{JSONObject args=obj("project",((String[])project.getTag())[project.getSelectedItemPosition()],"kind",kind.getSelectedItem().toString(),"memo",memo.getText().toString(),"requestId",requestId,"version",version==null?JSONObject.NULL:version);if(previous!=null)objMerge(args,"reissueOf",previous.optString("id"));rpc("createDocument",args,r->{group="documents";reload();});});button("���",()->businessList("documents"));}
